  16 => 
  array (
    'id' => 'art-017',
    'categoria' => 'ART y Cobertura',
    'pregunta' => '¿Qué es la SRT?',
    'respuesta_corta' => 'La Superintendencia de Riesgos del Trabajo (SRT) es el organismo que controla a las ART',
    'respuesta_completa' => '<div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">y protege los derechos de los trabajadores.</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">La SRT supervisa que las ART cumplan con sus obligaciones, controla las prestaciones</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">médicas y económicas, y recibe denuncias cuando hay incumplimientos de la aseguradora.</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">⚖️ ¿Qué dice la ley? La Superintendencia de Riesgos del Trabajo es la autoridad de</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">aplicación encargada de fiscalizar el sistema de riesgos del trabajo en todo el país.</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">📌 Podés acudir a la SRT para:</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">● Denunciar incumplimientos de la ART.</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">● Informarte sobre tus derechos.</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">● Reclamar cuando la ART no responde correctamente.</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">📄 Qué conviene hacer:</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">● Conservar toda la documentación del expediente.</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">● Registrar los reclamos que le hiciste a la ART.</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">● Presentar la denuncia si la aseguradora incumple sus obligaciones.</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">📝 Consejo práctico: Antes de resignarte a una negativa de la ART, verificá si</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">corresponde hacer un reclamo ante la SRT o directamente ante la Comisión Médica.</div>',
    'definiciones_relacionadas' => 
    array (
    ),
    'lesiones_relacionadas' => 
    array (
    ),
    'artículos_relacionados' => 
