  26 => 
  array (
    'id' => 'art-031',
    'categoria' => 'ART y Cobertura',
    'pregunta' => '¿Qué es la asistencia médica obligatoria de la ART?',
    'respuesta_corta' => 'Es el conjunto de prestaciones médicas que la ART tiene que darte sin costo mientras dure',
    'respuesta_completa' => '<div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">tu tratamiento.</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">Desde que sufrís un accidente de trabajo o una enfermedad profesional, la ART tiene la</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">obligación de garantizarte toda la atención médica necesaria hasta que te recuperes o</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">alcances la estabilidad médica.</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">⚖️ ¿Qué dice la ley? El art. 20 de la Ley 24.557 obliga a la ART a brindar las prestaciones</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">médicas necesarias derivadas del accidente o enfermedad laboral.</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">📌 La cobertura incluye:</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">● Consultas médicas.</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">● Estudios y diagnósticos.</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">● Cirugías e internaciones.</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">● Medicamentos.</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">● Prótesis y órtesis.</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">● Rehabilitación y kinesiología.</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">● Traslados, cuando son necesarios.</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">📄 Qué conviene hacer:</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">● Guardar todas las órdenes médicas.</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">● Pedir por escrito cualquier prestación que te nieguen.</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">● Reclamar ante la Comisión Médica si la ART demora o rechaza tratamientos.</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">📝 Consejo práctico: La ART no puede suspender ni limitar tu tratamiento sin un</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">fundamento médico. Si necesitás una prestación y no te la autorizan, reclamá de inmediato</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">y por escrito.</div>',
    'definiciones_relacionadas' => 
    array (
    ),
    'lesiones_relacionadas' => 
    array (
    ),
    'artículos_relacionados' => 
