  31 => 
  array (
    'id' => 'art-036',
    'categoria' => 'ART y Cobertura',
    'pregunta' => '¿Qué pasa si vuelvo a trabajar y reaparecen los síntomas?',
    'respuesta_corta' => 'Si reaparecen después del alta, podés pedir que la ART vuelva a evaluar tu caso y siga',
    'respuesta_completa' => '<div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">brindando prestaciones.</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">Si volviste a trabajar después del alta médica y te vuelven las molestias relacionadas con el</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">mismo accidente o enfermedad profesional, podés pedir una nueva evaluación en lugar de</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">resignarte a convivir con el dolor.</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">⚖️ ¿Qué dice la ley? Cuando hay relación entre los nuevos síntomas y el accidente laboral</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">original, la ART tiene que analizar de nuevo el caso y brindar las prestaciones que</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">correspondan.</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">📌 Tus derechos incluyen:</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">● Pedir una nueva atención médica.</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">● Solicitar la reapertura del expediente.</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">● Continuar con el tratamiento, si corresponde.</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">📄 Qué conviene hacer:</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">● Consultar de inmediato al médico.</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">● Informar la situación a la ART.</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">● Conservar estudios y antecedentes médicos.</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">📝 Consejo práctico: No minimices una reaparición de síntomas. Cuanto antes la</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">informes, más fácil va a ser acreditar que deriva del accidente original.</div>',
    'definiciones_relacionadas' => 
