  39 => 
  array (
    'id' => 'art-044',
    'categoria' => 'ART y Cobertura',
    'pregunta' => '¿Qué hago si la ART me manda a un médico que no es especialista?',
    'respuesta_corta' => 'Tenés derecho a una atención adecuada. Si el profesional asignado no es el especialista',
    'respuesta_completa' => '<div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">que necesitás, podés reclamar el cambio.</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">La ART tiene que garantizarte una atención médica acorde al tipo de lesión que sufriste. Si</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">el profesional asignado no tiene la especialidad necesaria, podés pedir que te atienda un</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">médico especializado.</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">⚖️ ¿Qué dice la ley? La Ley 24.557 garantiza las prestaciones médicas necesarias para la</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">recuperación del trabajador accidentado, lo que incluye una atención acorde a la</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">complejidad de la lesión.</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">📌 Tus derechos incluyen:</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">● Recibir atención de un profesional idóneo para tu lesión.</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">● Solicitar el cambio de médico si la atención no es adecuada.</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">● Reclamar ante la Comisión Médica si la ART no responde.</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">📄 Qué conviene hacer:</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">● Presentar el pedido de cambio por escrito.</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">● Guardar estudios, recetas e informes médicos.</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">● Conservar copia de todos los reclamos que hiciste.</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">📝 Consejo práctico: No aceptes una atención que pueda perjudicar tu recuperación. Si la</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">ART se niega a darte un especialista, buscá asesoramiento para hacer valer tu derecho.</div>',
    'definiciones_relacionadas' => 
    array (
    ),
    'lesiones_relacionadas' => 
    array (
    ),
    'artículos_relacionados' => 
    array (
