  ),
  40 => 
  array (
    'id' => 'art-045',
    'categoria' => 'ART y Cobertura',
    'pregunta' => '¿La ART me cubre si me lastimé en un viaje de trabajo?',
    'respuesta_corta' => 'Sí. Si el accidente ocurrió durante un viaje por motivos laborales, la ART tiene que cubrirte.',
    'respuesta_completa' => '<div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">Los accidentes durante un viaje de trabajo también se consideran accidentes laborales,</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">siempre que exista relación con las tareas que te encomendó tu empleador.</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">⚖️ ¿Qué dice la ley? El art. 6 de la Ley 24.557 considera accidente de trabajo al ocurrido</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">con motivo o en ocasión del trabajo, sin importar el lugar donde suceda.</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">📌 Tus derechos incluyen:</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">● Atención médica completa.</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">● Rehabilitación y medicamentos.</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">● Prestaciones económicas, si corresponde.</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">📄 Qué conviene hacer:</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">● Informar el accidente de inmediato.</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">● Guardar pasajes, reservas o comprobantes del viaje.</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">● Conservar certificados médicos y toda la documentación.</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">📝 Consejo práctico: Si el viaje fue organizado o autorizado por tu empleador, reuní toda</div><div style="display: block; margin-top: 12px; margin-bottom: 12px; line-height: 1.6;">la documentación posible para demostrar que estabas cumpliendo tareas laborales.</div>',
    'definiciones_relacionadas' => 
    array (
    ),
    'lesiones_relacionadas' => 
    array (
    ),
    'artículos_relacionados' => 
    array (
